using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Quotations.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Quotations.Commands.SendQuotation;public sealed class SendQuotationCommandHandler(IQuotationRepository repository,IApplicationDbContext db):IRequestHandler<SendQuotationCommand,Result<QuotationDto>>{public async Task<Result<QuotationDto>>Handle(SendQuotationCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<QuotationDto>(QuotationErrors.NotFound);if(e.Status.ToString()!="Draft")return Result.Failure<QuotationDto>(QuotationErrors.NotDraft);e.MarkAsSent(request.SentAt);await db.SaveChangesAsync(cancellationToken);return Result.Success(QuotationDto.FromEntity(e));}}
